/// One constant per extended error code this specification declares
/// (SPEC §7.3 item 9), named for its local part.
///
/// Emit these rather than a string literal: the code is read from the
/// specification, so it cannot name a code the specification never
/// declared.
pub mod error_codes {
    /// `auth/passkey/admin-list:notAdministrator`
    ///
    /// The producer holds no administrator standing at the consumer. Returned before `payload.subject` is looked at, so it reveals nothing about the subject.
    ///
    /// Declared `retryable: false`.
    pub const NOT_ADMINISTRATOR: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "auth/passkey/admin-list:notAdministrator",
        retryable: false,
    };
    /// `auth/passkey/admin-list:subjectNotMember`
    ///
    /// The subject is within the administrator's authority and known to the consumer, but is not a current member — they have left, been removed, or not yet been admitted. Their credentials answer nothing, so none are listed.
    ///
    /// Declared `retryable: false`.
    pub const SUBJECT_NOT_MEMBER: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "auth/passkey/admin-list:subjectNotMember",
        retryable: false,
    };
    /// `auth/passkey/admin-list:subjectUnknown`
    ///
    /// No subject by that identifier is within the administrator's authority. Returned identically for a subject the consumer has never heard of and for one outside the administrator's authority, so the code cannot be used to probe who is a member elsewhere.
    ///
    /// Declared `retryable: false`.
    pub const SUBJECT_UNKNOWN: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "auth/passkey/admin-list:subjectUnknown",
        retryable: false,
    };
    /// `auth/passkey/admin-list:purposeNotSupported`
    ///
    /// The consumer does not disclose credentials of this purpose to administrators — for example it issues no step-up credentials, or keeps session credentials to their owner's own auth/passkey/list.
    ///
    /// Declared `retryable: false`.
    pub const PURPOSE_NOT_SUPPORTED: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "auth/passkey/admin-list:purposeNotSupported",
        retryable: false,
    };
}
