    /// Each fixture in `payload.invalid-examples.json` MUST be
    /// rejected by at least one of: serde deserialization, or
    /// JSON-Schema validation under the `validate` feature. The
    /// fixture file documents the producer-side bug class that
    /// each payload exemplifies; this generated test pins it.
    #[cfg(feature = "validate")]
    #[test]
    fn rejects_invalid_examples() {
        use crate::validate::ValidatedPayload;
        let fixtures: &[(&str, &str)] = &[
            (
                "Missing subject — an administrator lists one named subject; the owner's own listing is auth/passkey/list.",
                "{\n  \"purpose\": \"stepUp\"\n}",
            ),
            (
                "Missing purpose — there is no default, so the inventory read is always the one asked for.",
                "{\n  \"subject\": \"did:webvh:QmCarolScid3:acme-vtc.example:carol\"\n}",
            ),
            ("Empty subject.", "{\n  \"purpose\": \"stepUp\",\n  \"subject\": \"\"\n}"),
            (
                "Unknown purpose.",
                "{\n  \"purpose\": \"recovery\",\n  \"subject\": \"did:webvh:QmCarolScid3:acme-vtc.example:carol\"\n}",
            ),
            (
                "Several subjects — one subject per request, each authorised on its own.",
                "{\n  \"purpose\": \"stepUp\",\n  \"subject\": [\n    \"did:webvh:QmCarolScid3:acme-vtc.example:carol\",\n    \"did:webvh:QmErinScid4:acme-vtc.example:erin\"\n  ]\n}",
            ),
            (
                "Unknown top-level member.",
                "{\n  \"includePublicKeys\": true,\n  \"purpose\": \"stepUp\",\n  \"subject\": \"did:webvh:QmCarolScid3:acme-vtc.example:carol\"\n}",
            ),
            (
                "Bare/unnamespaced ext key.",
                "{\n  \"ext\": {\n    \"bare-key\": {\n      \"anything\": \"here\"\n    }\n  },\n  \"purpose\": \"stepUp\",\n  \"subject\": \"did:webvh:QmCarolScid3:acme-vtc.example:carol\"\n}",
            ),
        ];
        for (i, (note, raw)) in fixtures.iter().enumerate() {
            let value: serde_json::Value = match serde_json::from_str(raw) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let serde_ok = serde_json::from_value::<super::Payload>(value.clone()).is_ok();
            let schema_ok = super::Payload::validate_value(&value).is_ok();
            assert!(
                !(serde_ok && schema_ok),
                "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
                i + 1,
                note,
                raw
            );
        }
    }
